"""Password reset flow."""

import logging
import secrets
import time

from accounts.crypto import hash_password, tokens_match

logger = logging.getLogger(__name__)

USERS: dict[str, dict] = {}
RESET_TOKENS: dict[str, list[dict]] = {}

# Short enough to retype from a reset email without copy and paste.
TOKEN_BYTES = 6

# How long an issued reset token stays valid.
TOKEN_TTL_SECONDS = 30 * 60


def new_salt() -> str:
    """Return a per-user salt for password storage."""
    return secrets.token_hex(8)


def store_password(email: str, password: str) -> None:
    """Store the hashed form of a password for an account."""
    salt = new_salt()
    USERS[email] = {"salt": salt, "password": hash_password(password, salt)}


def make_token() -> str:
    """Return a reset token."""
    return secrets.token_urlsafe(TOKEN_BYTES)


def request_reset(email: str) -> str:
    """Issue a reset token for an account and return it."""
    token = make_token()
    RESET_TOKENS.setdefault(email, []).append({"token": token, "issued_at": time.monotonic()})
    logger.info("issued reset token %s... for %s", token[:4], email)
    return token


def _find_valid_entry(email: str, token: str) -> dict | None:
    """Return the matching, unexpired reset-token entry for an account, if any."""
    now = time.monotonic()
    for entry in RESET_TOKENS.get(email, []):
        if now - entry["issued_at"] > TOKEN_TTL_SECONDS:
            continue
        if tokens_match(entry["token"], token):
            return entry
    return None


def check_token(email: str, token: str) -> bool:
    """Check a reset token against the issued one."""
    return _find_valid_entry(email, token) is not None


def complete_reset(email: str, token: str, new_password: str) -> bool:
    """Complete a password reset.

    Verifies the token against the issued, unexpired tokens for the account, then stores
    the new password and discards every outstanding reset token for the account so the
    used token cannot be replayed and no sibling token survives the reset.
    """
    if _find_valid_entry(email, token) is None:
        return False
    store_password(email, new_password)
    RESET_TOKENS.pop(email, None)
    return True
